section.programlisting:
// Инициализация главного окна
MainWindow window = new MainWindow();
window.initialize();
window.show();

// Создание документа и ввод текста
DocumentArea doc = new DocumentArea();
doc.insertText("Введение\nЭто пример текста для демонстрации возможностей MyWord.");

// Применение стиля и форматирование
StyleManager styles = new StyleManager();
styles.applyStyle("Заголовок 1");

TextFormatter fmt = new TextFormatter();
fmt.setBold(true);
fmt.setAlignment("center");

// Проверка орфографии
SpellChecker speller = new SpellChecker();
speller.checkWord("текста"); // слово верное
speller.checkWord("програма"); // слово с ошибкой
String[] suggestions = speller.suggestCorrections("програма");
System.out.println("Варианты исправления: " + Arrays.toString(suggestions));

ImageHandler img = new ImageHandler();
img.insertImage("C:/Users/User/Pictures/diagram.png");
img.resize(400, 300);
// В перспективе можно установить обтекание:
// img.setWrapping("square");

SearchReplaceDialog sr = new SearchReplaceDialog();
sr.search("пример", false); // поиск без учёта регистра
sr.replace("пример", "образец");

PrintPreview preview = new PrintPreview();
preview.showPreview();
preview.print("HP LaserJet", 2); // печать двух копий

// Сохранение документа
FileIO fileIO = new FileIO();
fileIO.save("document.myword", doc.getText());
